<script lang="ts">
	import { BatteryCharging, Camera, Check, Home, Pencil, RefreshCw, Thermometer, X } from '@lucide/svelte';
	import { onMount } from 'svelte';
	import { getBmsDashboardSnapshot, getSiteName, hasBmsSession, setSiteName, type BmsDashboardItem } from '$lib/services/bms-api';

	let { onOpenString }: { onOpenString: (stringIndex: number) => void } = $props();
	let siteName=$state('My Monitoring Site'),siteDraft=$state(''),editingSite=$state(false),savingSite=$state(false);
	let cameraEnabled=$state(false),items=$state<BmsDashboardItem[]>([]),loading=$state(false),error=$state('');

	onMount(()=>{void load();const timer=setInterval(()=>void load(false),15000);return()=>clearInterval(timer)});
	async function load(showActivity=true){if(!hasBmsSession()){items=[];error='Authenticate with the BMS platform to load live dashboard data.';return}if(showActivity)loading=true;try{const [name,data]=await Promise.all([getSiteName().catch(()=>siteName),getBmsDashboardSnapshot()]);siteName=name;items=data;error=''}catch(cause){error=cause instanceof Error?cause.message:'Unable to load the BMS dashboard.'}finally{loading=false}}
	function startEdit(){siteDraft=siteName;editingSite=true}
	async function saveSite(){const value=siteDraft.trim();if(!value){error='Site name cannot be empty.';return}if(value.length>120){error='Site name cannot exceed 120 characters.';return}savingSite=true;try{siteName=hasBmsSession()?await setSiteName(value):value;editingSite=false;error=''}catch(cause){error=cause instanceof Error?cause.message:'Unable to save the site name.'}finally{savingSite=false}}
	function alarms(item:BmsDashboardItem){const s=item.telemetry.summary,c=item.config,reasons:string[]=[];const highR=c.highResistanceThreshold||Math.round(c.rNew*2.3);if(s.maxResistance!==null&&highR>0&&s.maxResistance>=highR)reasons.push('High internal resistance');if(s.maxTemperature!==null&&c.highTemperatureThreshold>0&&s.maxTemperature>=c.highTemperatureThreshold)reasons.push('High temperature');if(s.minVoltage!==null&&c.lowVoltageThreshold>0&&s.minVoltage<=c.lowVoltageThreshold)reasons.push('Low voltage');if(s.maxVoltage!==null&&c.highVoltageThreshold>0&&s.maxVoltage>=c.highVoltageThreshold)reasons.push('High voltage');return reasons}
	function primaryAlarm(reasons:string[]){if(reasons.includes('High internal resistance'))return'IR';if(reasons.includes('High temperature'))return'T';if(reasons.some(value=>value.includes('voltage')))return'V';return'Alarm'}
	function disconnected(item:BmsDashboardItem){const s=item.telemetry.summary;return!item.telemetry.active||[s.avgVoltage,s.avgResistance,s.stringVoltage,s.stringCurrent,s.avgTemperature].every(value=>value===null)}
	function statusFor(item:BmsDashboardItem){const reasons=alarms(item);if(reasons.length)return{label:`Alarm (${primaryAlarm(reasons)})`,tone:'alarm',reasons};if(disconnected(item))return{label:'Disconnected',tone:'off',reasons};return{label:'Normal',tone:'ok',reasons}}
	function channel(on:boolean){return on?'On':'Off'}
	function time(value:number|null){return value?new Date(value).toLocaleString():'N/A'}
	function number(value:number|null,digits=3){return value===null?'N/A':value.toFixed(digits)}
</script>

<section class="page">
	<div class="site-card"><div class="site-name"><span class="site-icon"><Home size={20}/></span>{#if editingSite}<input maxlength="120" bind:value={siteDraft}/><button aria-label="Save site name" disabled={savingSite} onclick={saveSite}><Check size={18}/></button><button aria-label="Cancel editing" onclick={()=>editingSite=false}><X size={18}/></button>{:else}<div><span>Monitoring site</span><h2>{siteName}</h2></div><button aria-label="Edit site name" onclick={startEdit}><Pencil size={17}/></button>{/if}</div><div class="summary-pills">{#each items as item (item.config.id)}{@const status=statusFor(item)}<button onclick={()=>onOpenString(item.config.stringIndex)}><BatteryCharging size={16}/><strong>{item.config.stringName}</strong><span>{item.config.cellQty} cells</span><em class={status.tone}>{status.tone==='off'?'DISCONNECTED':status.tone==='alarm'?status.label.toUpperCase():'OK'}</em></button>{/each}</div><button class:loading class="refresh" aria-label="Refresh dashboard" disabled={loading} onclick={()=>load()}><RefreshCw size={18}/></button></div>
	{#if error}<div class="request-error">{error}</div>{/if}

	<section class="thermal-card"><header><div><span><Thermometer size={19}/></span><div><h3>Thermal Camera</h3><p>Optional battery room thermal monitoring.</p></div></div><button class:active={cameraEnabled} onclick={()=>cameraEnabled=!cameraEnabled}><Camera size={16}/>{cameraEnabled?'On':'Off'}</button></header><div class="thermal-empty"><Thermometer size={21}/><span>No thermal data available</span></div></section>

	<div class="table-wrap"><table><thead><tr><th>String name</th><th>Status</th><th>Cell vol</th><th>Cell rst</th><th>String vol</th><th>Current</th><th>Ambient</th><th>SoC (%)</th><th>SoH (%)</th><th>Last update</th></tr></thead><tbody>{#if items.length===0}<tr><td colspan="10" class="empty"><BatteryCharging size={28}/><strong>No battery strings configured</strong><span>Add a string in Battery Strings to begin monitoring.</span></td></tr>{:else}{#each items as item (item.config.id)}{@const status=statusFor(item)}{@const summary=item.telemetry.summary}<tr onclick={()=>onOpenString(item.config.stringIndex)}><td><strong class="link">{item.config.stringName}</strong><small>{item.config.cellQty} cells</small></td><td title={status.reasons.join(', ')}><span class="state"><i class={status.tone}></i>{status.label}</span></td><td><span class="channel"><i class:live={item.telemetry.active&&summary.avgVoltage!==null}></i>{channel(item.telemetry.active&&summary.avgVoltage!==null)}</span></td><td><span class="channel"><i class:live={item.telemetry.active&&summary.avgResistance!==null}></i>{channel(item.telemetry.active&&summary.avgResistance!==null)}</span></td><td><span class="channel"><i class:live={item.telemetry.active&&summary.stringVoltage!==null}></i>{channel(item.telemetry.active&&summary.stringVoltage!==null)}</span></td><td><span class="channel"><i class:live={item.telemetry.active&&summary.stringCurrent!==null}></i>{channel(item.telemetry.active&&summary.stringCurrent!==null)}</span></td><td><span class="channel"><i class:live={item.telemetry.active&&summary.avgTemperature!==null}></i>{channel(item.telemetry.active&&summary.avgTemperature!==null)}</span></td><td>{number(summary.stringSoC)}</td><td>{number(summary.stringSoH)}</td><td>{time(item.telemetry.calculation.snapshotTimestamp)}</td></tr>{/each}{/if}</tbody></table></div>
</section>

<style>
	.page{animation:enter .18s ease-out}.site-card{display:flex;align-items:center;gap:18px;min-height:80px;padding:14px 16px;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.site-name{display:flex;align-items:center;gap:9px;min-width:240px}.site-icon{display:grid;width:36px;height:36px;place-items:center;border-radius:9px;color:#2653ba;background:#eaf0ff}.site-name div>span{color:#8792a4;font-size:13px}.site-name h2{margin:3px 0 0;color:#273954;font-size:19px;font-weight:500}.site-name input{width:190px;height:38px;padding:0 10px;border:1px solid #cbd7e8;border-radius:7px;font:inherit}.site-name button,.refresh{display:grid;width:34px;height:34px;place-items:center;border:1px solid #dce4ef;border-radius:7px;color:#526784;background:#fff;cursor:pointer}.summary-pills{display:flex;gap:8px;margin-left:auto;overflow-x:auto}.summary-pills button{display:flex;align-items:center;gap:7px;min-height:38px;padding:0 9px;border:1px solid #e1e6ee;border-radius:20px;color:#41516c;background:#fff;white-space:nowrap;font:inherit;cursor:pointer}.summary-pills strong{font-size:14px;font-weight:500}.summary-pills span{color:#7f8a9c;font-size:13px}.summary-pills em{padding:4px 7px;border-radius:11px;font-size:10px;font-style:normal}.summary-pills em.ok{color:#26764d;background:#eaf8ef}.summary-pills em.off{color:#687588;background:#eef1f5}.summary-pills em.alarm{color:#bd2b20;background:#fff0ef}.refresh{flex:0 0 auto}.refresh.loading :global(svg){animation:spin .8s linear infinite}.request-error{margin-top:12px;padding:10px 12px;border:1px solid #f2d1ce;border-radius:8px;color:#b42318;background:#fff3f2;font-size:14px}.thermal-card{margin-top:14px;overflow:hidden;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.thermal-card header{display:flex;align-items:center;justify-content:space-between;padding:13px 16px;border-bottom:1px solid #edf0f4}.thermal-card header>div{display:flex;align-items:center;gap:10px}.thermal-card header>div>span{display:grid;width:34px;height:34px;place-items:center;border-radius:8px;color:#c55843;background:#fff0ec}.thermal-card h3{margin:0;color:#30415c;font-size:16px;font-weight:500}.thermal-card p{margin:4px 0 0;color:#8792a4;font-size:14px}.thermal-card button{display:flex;align-items:center;gap:6px;height:33px;padding:0 10px;border:1px solid #d9e1ec;border-radius:16px;color:#6d798b;background:#fff;font:inherit;cursor:pointer}.thermal-card button.active{border-color:#b9dfc9;color:#24764d;background:#f1fbf5}.thermal-empty{display:flex;align-items:center;gap:8px;margin:12px 16px;padding:11px 12px;border-radius:8px;color:#7c899d;background:#f7f9fc}.table-wrap{margin-top:14px;overflow-x:auto;border-top:1px solid #e5ebf3;border-bottom:1px solid #e5ebf3;background:#fff}table{width:100%;min-width:1180px;border-collapse:collapse}th,td{padding:13px 15px;border-bottom:1px solid #edf1f6;color:#526179;text-align:left}th{color:#79869a;background:#f8faff;font-size:13px;font-weight:500;text-transform:uppercase}td{font-size:15px}tbody tr:not(:has(.empty)){cursor:pointer;transition:background .15s}tbody tr:not(:has(.empty)):hover{background:#fafcff}.link{color:#1b4eae;font-weight:500}td small{display:block;margin-top:3px;color:#8995a7;font-size:14px}.state,.channel{display:inline-flex;align-items:center;gap:7px;white-space:nowrap}.state i,.channel i{width:7px;height:7px;border-radius:50%;background:#9ba6b5}.state i.ok,.channel i.live{background:#28a764}.state i.alarm{background:#df3328}.state i.off{background:#9ba6b5}.empty{height:330px;text-align:center}.empty :global(svg),.empty strong,.empty span{display:block;margin-right:auto;margin-left:auto}.empty :global(svg){margin-bottom:11px;color:#6d8bd1}.empty strong{color:#33435e;font-size:16px;font-weight:500}.empty span{margin-top:7px;color:#7c889d}@keyframes spin{to{transform:rotate(360deg)}}@keyframes enter{from{opacity:0;transform:translateY(4px)}}@media(max-width:950px){.site-card{align-items:flex-start;flex-wrap:wrap}.summary-pills{order:3;width:100%;margin-left:0}.site-name{flex:1}.table-wrap{margin-top:12px}}@media(max-width:650px){.site-name{min-width:0}.thermal-card header{align-items:flex-start;gap:12px}.site-card{gap:10px}}
</style>
